insert into products (category, code, name, name_zh, sku, collection, material, weave, thread_count, fill, description, description_zh, best_for, best_for_zh, attributes, ratings, sort_order, active) values
  ('sheet', 'P001', 'SUPIMA Percale', null, 'TN-SP-300-WT', 'Signature Collection', 'Cotton', 'Percale', 300, null, 'Woven from SUPIMA cotton — representing less than 1% of the world''s cotton supply. Its extra-long fibres produce a percale with exceptional strength and a cool, clean hand-feel that improves with every wash.', '採用全球不到1%的SUPIMA棉紡製而成，超長纖維打造出高強度平織床單，觸感清爽潔淨，每次洗滌後更加柔順舒適。', '["Hot Sleepers","Warm Climates","Pet Owners","Durability Seekers"]'::jsonb, '["易出汗體質","溫熱氣候","有養寵物者","注重耐用性"]'::jsonb, '{"temperature":"Cooling","moisture_wicking":"Moderate","softness":"Crisp","durability":"High","hypoallergenic":false,"wrinkle_resistance":"Low","weave_tightness":"Tight"}'::jsonb, '{"breathability":5,"wicking":3,"warmth":1,"softness":3}'::jsonb, 0, true),
  ('sheet', 'P002', 'Egyptian Cotton Sateen', null, 'TN-CS-400-IV', 'Charisma Series', 'Cotton', 'Sateen', 400, null, 'Long-staple Egyptian cotton in a four-over-one satin weave creates a luminous, silky surface with a subtle sheen. Drapes beautifully, resists wrinkles, and feels indulgent from the first night.', '長絨埃及棉以四上一下緞紋織法織成，呈現光澤絲滑的表面。垂墜感佳、抗皺性強，從第一個夜晚起就帶來奢華享受。', '["Average Sleepers","Cool Climates","Low Maintenance","Luxury Feel"]'::jsonb, '["一般體質","涼爽氣候","低保養需求","奢華觸感"]'::jsonb, '{"temperature":"Neutral","moisture_wicking":"Low","softness":"Smooth","durability":"Medium","hypoallergenic":false,"wrinkle_resistance":"High","weave_tightness":"Medium"}'::jsonb, '{"breathability":2,"wicking":2,"warmth":3,"softness":5}'::jsonb, 1, true),
  ('sheet', 'P003', 'Topcell™ Lyocell', null, 'TN-TC-HG', 'Topcell Pro', 'Tencel Lyocell', 'Plain', null, null, 'Tonia Nicole''s signature Topcell™ uses pine-pulp Lyocell with Faser-Lock™ British technology — enhanced fibre bonding that triples durability versus standard Lyocell. Feather-soft, hypoallergenic, and remarkably cool.', '東妮寢飾獨家Topcell™採用松木漿天絲，結合英國Faser-Lock™技術，纖維結合強度是標準天絲的三倍。超柔、低敏、清涼感卓越。', '["Hot Sleepers","Sensitive Skin","Night Sweats","Low Maintenance"]'::jsonb, '["易出汗體質","敏感肌膚","盜汗問題","低保養需求"]'::jsonb, '{"temperature":"Cooling","moisture_wicking":"High","softness":"Ultra-Soft","durability":"High","hypoallergenic":true,"wrinkle_resistance":"High","weave_tightness":"Medium"}'::jsonb, '{"breathability":5,"wicking":5,"warmth":1,"softness":5}'::jsonb, 2, true),
  ('sheet', 'P004', 'TN Tencel 80S', null, 'TN-TN-80S', 'Eco Series', 'Tencel Lyocell', 'Plain', null, null, 'OEKO-TEX certified Tencel Lyocell in an 80S yarn count. Silky smooth, hypoallergenic, and closed-loop manufactured — absorbs moisture 50% faster than cotton while remaining completely breathable.', 'OEKO-TEX認證天絲Lyocell 80支紗，絲滑觸感、低敏特性、閉環製程——吸濕速度比棉快50%，同時保持完全透氣。', '["Hot Sleepers","Allergic/Sensitive Skin","Eco-Conscious","Night Sweats"]'::jsonb, '["易出汗體質","過敏／敏感肌","環保意識","盜汗問題"]'::jsonb, '{"temperature":"Cooling","moisture_wicking":"High","softness":"Smooth","durability":"Medium","hypoallergenic":true,"wrinkle_resistance":"Medium","weave_tightness":"Medium"}'::jsonb, '{"breathability":4,"wicking":5,"warmth":2,"softness":4}'::jsonb, 3, true),
  ('sheet', 'P005', 'European Linen', null, 'TN-LN-EU', 'Natural Edit', 'Linen', 'Plain', null, null, 'Stone-washed European flax linen — the most breathable natural fibre available. Inherently temperature-regulating and only gets softer, more supple, and more beautiful with every year of use.', '石洗歐洲亞麻——最透氣的天然纖維。天然調溫特性讓您保持舒適，越洗越柔軟，越用越美麗。', '["Hot Sleepers","Warm Climates","Texture Lovers","Durability Seekers"]'::jsonb, '["易出汗體質","溫熱氣候","喜愛質感者","注重耐用性"]'::jsonb, '{"temperature":"Cooling","moisture_wicking":"Moderate","softness":"Textured","durability":"High","hypoallergenic":false,"wrinkle_resistance":"Low","weave_tightness":"Loose"}'::jsonb, '{"breathability":5,"wicking":3,"warmth":1,"softness":2}'::jsonb, 4, true),
  ('sheet', 'P006', 'Silk 22MM', null, 'TN-SK-22M', 'Prestige', 'Silk', 'Plain', null, null, '22-momme mulberry silk — Tonia Nicole''s premium grade. Naturally hypoallergenic protein fibre that regulates temperature, reduces friction on hair and skin, and is recommended by dermatologists for eczema-prone sleepers.', '22姆米桑蠶絲——東妮寢飾頂級規格。天然低敏蛋白纖維，調節體溫、減少對髮膚的摩擦，皮膚科醫師推薦給濕疹肌膚者使用。', '["Sensitive Skin","Allergic/Eczema","Hair & Skin Care","Luxury"]'::jsonb, '["敏感肌膚","過敏／濕疹","髮膚保護","頂級奢華"]'::jsonb, '{"temperature":"Cooling","moisture_wicking":"Moderate","softness":"Ultra-Soft","durability":"Low","hypoallergenic":true,"wrinkle_resistance":"Medium","weave_tightness":"Tight"}'::jsonb, '{"breathability":4,"wicking":3,"warmth":3,"softness":5}'::jsonb, 5, true),
  ('sheet', 'P007', 'Brushed Flannel Cotton', null, 'TN-FL-BRS', 'Winter Comfort', 'Flannel', 'Plain', null, null, 'Double-brushed cotton flannel for exceptional warmth and cloud-like softness. Ideal for cold bedrooms and winter nights — wrap yourself in the feeling of a warm embrace.', '雙面刷毛棉法蘭絨，提供卓越保暖性與如雲朵般的柔軟感。適合寒冷臥室與冬夜——如同溫暖擁抱般的睡眠體驗。', '["Cold Sleepers","Cold Climates","Winter Comfort"]'::jsonb, '["怕冷體質","寒冷氣候","冬日舒適"]'::jsonb, '{"temperature":"Warming","moisture_wicking":"Moderate","softness":"Ultra-Soft","durability":"Medium","hypoallergenic":false,"wrinkle_resistance":"Low","weave_tightness":"Medium"}'::jsonb, '{"breathability":2,"wicking":3,"warmth":5,"softness":5}'::jsonb, 6, true),
  ('sheet', 'P008', 'CoolTouch Nylon Fiber', null, 'TN-NC-TC', 'TopCool Series', 'Nylon Fiber', 'Plain', null, null, 'Tonia Nicole''s high-performance nylon fibre delivers an instant cooling sensation on contact, wicks moisture rapidly, and dries in a fraction of the time of cotton — perfect for hot sleepers who prioritise low-maintenance care.', '東妮寢飾高性能尼龍纖維，接觸瞬間帶來清涼感，快速吸濕導汗，乾燥速度遠快於棉——適合重視低保養的熱睡者。', '["Hot Sleepers","Night Sweats","Low Maintenance","Active Lifestyles"]'::jsonb, '["易出汗體質","盜汗問題","低保養需求","活躍生活型態"]'::jsonb, '{"temperature":"Cooling","moisture_wicking":"High","softness":"Smooth","durability":"High","hypoallergenic":false,"wrinkle_resistance":"High","weave_tightness":"Tight"}'::jsonb, '{"breathability":3,"wicking":5,"warmth":1,"softness":4}'::jsonb, 7, true),
  ('comforter', 'C001', 'Silk Comforter', null, 'TN-SK-CM-AS', 'Prestige', null, null, null, 'Silk', 'Mulberry silk fill with a naturally protein-rich structure that regulates temperature in all seasons. Lightweight, hypoallergenic, and breathable — the preferred choice for sensitive skin.', '桑蠶絲填充，天然蛋白質結構四季調溫。輕盈、低敏、透氣——敏感肌膚的首選棉被。', '["Sensitive Skin","Year-Round Use","Luxury","Hot Sleepers"]'::jsonb, '["敏感肌膚","四季適用","奢華體驗","易出汗體質"]'::jsonb, '{"warmth":"All-Season","temperature":"Cooling","hypoallergenic":true,"washable":false,"weight":"Light"}'::jsonb, '{"warmth":3,"breathability":5,"fluffiness":3}'::jsonb, 8, true),
  ('comforter', 'C002', 'Wool Comforter', null, 'TN-WL-CM-WN', 'Winter Comfort', null, null, null, 'Wool', 'Natural wool fill with an exceptional warmth-to-weight ratio. Naturally anti-static and moisture-regulating — ideal for cold sleepers who want substantial coverage without overheating.', '天然羊毛填充，保暖性與重量比卓越。天然防靜電、調節濕氣——適合怕冷且想要厚實包覆感而不悶熱的睡眠者。', '["Cold Sleepers","Winter Use","Temperature Regulation","Thick Coverage"]'::jsonb, '["怕冷體質","冬季使用","體溫調節","厚實包覆感"]'::jsonb, '{"warmth":"Winter","temperature":"Warming","hypoallergenic":false,"washable":false,"weight":"Heavy"}'::jsonb, '{"warmth":5,"breathability":4,"fluffiness":3}'::jsonb, 9, true),
  ('comforter', 'C003', 'Down Comforter', null, 'TN-DW-CM-WN', 'Signature Collection', null, null, null, 'Down', 'Premium white down clusters deliver outstanding warmth with remarkable lightness. High fill power creates a cloud-like loft — perfect for cold sleepers who prefer the enveloping feel of a fluffy duvet.', '頂級白鵝絨提供卓越保暖性與驚人輕盈感。高蓬鬆度打造如雲朵般的被體——適合喜愛蓬鬆包覆感的怕冷者。', '["Cold Sleepers","Lightweight Warmth","Fluffy Feel","Winter Use"]'::jsonb, '["怕冷體質","輕盈保暖","蓬鬆感","冬季使用"]'::jsonb, '{"warmth":"Winter","temperature":"Warming","hypoallergenic":false,"washable":false,"weight":"Light"}'::jsonb, '{"warmth":5,"breathability":5,"fluffiness":5}'::jsonb, 10, true),
  ('comforter', 'C004', 'TN Tech Fiber Comforter', null, 'TN-TF-CM-AS', 'TopCool Series', null, null, null, 'Tech Fiber', 'High-performance technical fiber fill that bounces back wash after wash. Machine washable, hypoallergenic, and available in summer, all-season, and winter weights — the practical choice for busy households.', '高性能科技纖維填充，每次洗滌後依然回彈蓬鬆。可機洗、低敏，夏季、四季及冬季重量均有提供——忙碌家庭的實用首選。', '["Easy Care","Allergy Sufferers","Year-Round Use","Busy Households"]'::jsonb, '["易於清洗","過敏體質","四季適用","忙碌家庭"]'::jsonb, '{"warmth":"All-Season","temperature":"Neutral","hypoallergenic":true,"washable":true,"weight":"Medium"}'::jsonb, '{"warmth":3,"breathability":4,"fluffiness":4}'::jsonb, 11, true),
  ('pillow', 'PL001', 'Hungarian Down Pillow', null, 'TN-DW-PL-HG', 'Signature Collection', null, null, null, 'Down', 'Premium Hungarian white down clusters deliver exceptional loft and an enveloping softness. Naturally insulating and breathable — the pillow that feels like sleeping on a cloud.', '頂級匈牙利白鵝絨提供卓越蓬鬆度與包覆柔軟感。天然保暖透氣——讓您體驗如睡在雲端般的枕頭感受。', '["Side Sleepers","Broad Shoulders","Luxury Feel","Cold Sleepers"]'::jsonb, '["側睡","寬肩體型","奢華觸感","怕冷體質"]'::jsonb, '{"loft":"High","firmness":"Soft","hypoallergenic":false,"temperature":"Neutral","adjustable":false}'::jsonb, '{}'::jsonb, 12, true),
  ('pillow', 'PL002', 'Memory Foam Contour Pillow', null, 'TN-MF-PL-CV', 'Topcell Pro', null, null, null, 'Memory Foam', 'Ergonomic contour shape with temperature-responsive memory foam that conforms precisely to the neck and shoulder curve. Provides targeted cervical support for back sleepers and those with neck tension.', '人體工學輪廓設計，記憶棉精準貼合頸肩曲線。為仰睡者及頸部緊繃者提供精確的頸椎支撐。', '["Back Sleepers","Neck Pain","Cervical Support","Broad Shoulders"]'::jsonb, '["仰睡","頸部疼痛","頸椎支撐","寬肩體型"]'::jsonb, '{"loft":"Medium","firmness":"Firm","hypoallergenic":false,"temperature":"Warming","adjustable":false}'::jsonb, '{}'::jsonb, 13, true),
  ('pillow', 'PL003', 'Shredded Latex Pillow', null, 'TN-LX-PL-SH', 'Natural Edit', null, null, null, 'Latex', 'Shredded natural latex fill with an adjustable loft — add or remove fill to dial in your perfect height. Naturally breathable, anti-microbial, and resilient. Ideal for combination sleepers who move during the night.', '碎片天然乳膠填充，可自由調整枕頭高度——增減填充量找到完美高度。天然透氣、抗菌、彈力持久，適合夜間翻身的多種睡姿者。', '["Combination Sleepers","Side Sleepers","Sensitive Skin","Hot Sleepers"]'::jsonb, '["多種睡姿","側睡","敏感肌膚","易出汗體質"]'::jsonb, '{"loft":"Medium","firmness":"Medium","hypoallergenic":true,"temperature":"Cooling","adjustable":true}'::jsonb, '{}'::jsonb, 14, true),
  ('pillow', 'PL004', 'Tech Fiber Pillow', null, 'TN-TF-PL-MD', 'TopCool Series', null, null, null, 'Tech Fiber', 'High-performance tech fiber fill that stays lofty wash after wash. Machine washable, fully hypoallergenic, and dries quickly — the practical choice for allergy sufferers and busy households.', '高性能科技纖維填充，每次洗滌後依然保持蓬鬆。可機洗、完全低敏、快乾——過敏體質及忙碌家庭的實用選擇。', '["Allergy Sufferers","Low Maintenance","Side Sleepers","Combination Sleepers"]'::jsonb, '["過敏體質","低保養需求","側睡","多種睡姿"]'::jsonb, '{"loft":"Medium","firmness":"Medium","hypoallergenic":true,"temperature":"Neutral","adjustable":false}'::jsonb, '{}'::jsonb, 15, true),
  ('pillow', 'PL005', 'Slim Down Pillow', null, 'TN-DW-PL-SL', 'Signature Collection', null, null, null, 'Down', 'A slim, low-loft down pillow designed specifically for stomach sleepers and those with a petite frame. Keeps the spine neutral and prevents neck strain — lightweight, whisper-soft, and unobtrusive.', '專為趴睡者及嬌小體型設計的低枕。保持脊椎中立、預防頸椎緊繃——輕盈、極柔、不累贅。', '["Stomach Sleepers","Petite Frame","Soft Feel","Low Loft Preference"]'::jsonb, '["趴睡","嬌小體型","柔軟觸感","偏好低枕"]'::jsonb, '{"loft":"Low","firmness":"Soft","hypoallergenic":false,"temperature":"Neutral","adjustable":false}'::jsonb, '{}'::jsonb, 16, true);
